import{_ as s,o as n,c as e,S as r}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Archlinux和Win 10 在 UEFI下 双启动","description":"实验室给配备了一台高性能的台式机,但是 UEFI 本身关不掉.而且有些操作还是离不开 Windows,于是便折腾 Win10 和 Archlinux 的双启动.\\n安装双系统基本上都是先装 Windows 再装 Linux 的.切忌这一点,安…","frontmatter":{"title":"Archlinux和Win 10 在 UEFI下 双启动","date":"2015-10-28 23:32","comments":true,"archives":2015,"tags":["linux"]},"headers":[],"relativePath":"posts/2015-10-28-uefi-dual-boot-archlinux/index.md","filePath":"posts/2015/2015-10-28-UEFI-dual-boot-Archlinux.md"}'),l={name:"posts/2015-10-28-uefi-dual-boot-archlinux/index.md"};function i(o,a,p,t,c,u){return n(),e("div",null,[...a[0]||(a[0]=[r(`<p>实验室给配备了一台高性能的台式机,但是 UEFI 本身关不掉.而且有些操作还是离不开 Windows,于是便折腾 Win10 和 Archlinux 的双启动. 安装双系统基本上都是先装 Windows 再装 Linux 的.切忌这一点,安装顺序反了会很麻烦.</p><h2 id="win10-配置" tabindex="-1">Win10 配置 <a class="header-anchor" href="#win10-配置" aria-label="Permalink to &quot;Win10 配置&quot;">​</a></h2><p>要安装 Archlinux,首先得对 Windows 进行相应的配置才行.Windows 的安装就不用我介绍了,大家基本都会的.</p><h2 id="uefi-secure-boot" tabindex="-1">UEFI Secure Boot <a class="header-anchor" href="#uefi-secure-boot" aria-label="Permalink to &quot;UEFI Secure Boot&quot;">​</a></h2><p>首先要进入 BIOS 把这个参数关掉,如果 BIOS 里面有快速启动之类的也关掉.</p><h2 id="fast-start-up" tabindex="-1">Fast Start-Up <a class="header-anchor" href="#fast-start-up" aria-label="Permalink to &quot;Fast Start-Up&quot;">​</a></h2><p>把 Win10 的这个加速系统开机的配置禁用掉,应该在电源管理界面可以禁用的.因为切换系统的话这个功能会导致你丢失数据.</p><h2 id="制作-arch-的-u-盘安装盘" tabindex="-1">制作 Arch 的 U 盘安装盘 <a class="header-anchor" href="#制作-arch-的-u-盘安装盘" aria-label="Permalink to &quot;制作 Arch 的 U 盘安装盘&quot;">​</a></h2><p>如果你简单的使用<a href="https://wiki.archlinux.org/index.php/USB_flash_installation_media#In_GNU.2FLinux" target="_blank" rel="noreferrer">dd</a>命令就可以成功安装那是最好不过的了,但是有时候事与愿违...</p><p>假设你用 dd 刻录好之后,然后用电脑 U 盘启动,出现启动菜单 选择 <code>Arch Linux archiso x86_64 UEFI CD</code> 之后遇到黑屏的问题.</p><p>你可以先试试<a href="https://wiki.archlinux.org/index.php/Unified_Extensible_Firmware_Interface#USB_media_gets_struck_with_black_screen" target="_blank" rel="noreferrer">禁用 KMS</a></p><p>如果这个不行的话,那说明你得采用第二个办法了,使用 GRUB 进行引导启动盘.</p><h2 id="手动制作启动盘" tabindex="-1">手动制作启动盘 <a class="header-anchor" href="#手动制作启动盘" aria-label="Permalink to &quot;手动制作启动盘&quot;">​</a></h2><p>因为要使用 GRUB 进行引导,所以不能使用 dd 刻录,dd 刻录的 U 盘有写保护,我们无法修改.我们得<a href="https://wiki.archlinux.org/index.php/USB_flash_installation_media#Using_manual_formatting" target="_blank" rel="noreferrer">手动制作安装盘</a></p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># mkdir -p /mnt/{iso,usb}</span></span>
<span class="line"><span style="color:#6A737D;"># mount -o loop archlinux-2015.10.01-dual.iso /mnt/iso</span></span>
<span class="line"><span style="color:#6A737D;"># mount /dev/sdXn /mnt/usb</span></span>
<span class="line"><span style="color:#6A737D;"># cp -a /mnt/iso/* /mnt/usb</span></span>
<span class="line"><span style="color:#6A737D;"># sync</span></span>
<span class="line"><span style="color:#6A737D;"># umount /mnt/iso</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>光是拷贝还不行,我们还得有引导信息. 使用 syslinux 进行<a href="https://wiki.archlinux.org/index.php/Syslinux#Manual_install" target="_blank" rel="noreferrer">引导</a></p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># cp -r /usr/lib/syslinux/bios/*.c32 /mnt/usb/arch/boot/syslinux/  ## copy ALL the *.c32 files from /usr/lib/syslinux/bios/, DO NOT SYMLINK</span></span>
<span class="line"><span style="color:#6A737D;"># extlinux --install /mnt/usb/arch/boot/syslinux/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>如果你的 U 盘是 MBR 格式的,记得使用 fdisk 把当前分区设置为活动分区. <code>fdisk /dev/sdX</code> 然后输入 <code>a</code> 命令,选择要设置的活动分区.</p><p>还有 U 盘寻找启动分区是根据 U 盘的 label 标签来寻找的,确保你的卷标是 <code>ARCH_2015XX</code> 格式. 如果你不想用卷标的话,还可以用 UUID. 查找你 U 盘的 UUID 的命令是 <code>sudo blkid</code>.</p><h2 id="制作-grub-standalone" tabindex="-1">制作 GRUB standalone <a class="header-anchor" href="#制作-grub-standalone" aria-label="Permalink to &quot;制作 GRUB standalone&quot;">​</a></h2><p>这才只是手动制作好了启动 U 盘.你还要切换成 GRUB 引导.通过下面的命令制作出一个带有所有模块的 GRUB 引导文件.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">grub-mkstandalone</span><span style="color:#005CC5;"> -d</span><span style="color:#032F62;"> /usr/lib/grub/x86_64-efi/</span><span style="color:#005CC5;"> -O</span><span style="color:#032F62;"> x86_64-efi</span><span style="color:#005CC5;"> --modules=</span><span style="color:#032F62;">&quot;part_gpt part_msdos&quot;</span><span style="color:#005CC5;"> --fonts=</span><span style="color:#032F62;">&quot;unicode&quot;</span><span style="color:#005CC5;"> --locales=</span><span style="color:#032F62;">&quot;en@quot&quot;</span><span style="color:#005CC5;"> --themes=</span><span style="color:#032F62;">&quot;&quot;</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> &quot;/tmp/grubx64_standalone.efi&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>生成的 grubx64_standalone.efi 就是我们需要的文件.</p><p>然后回到我们的那个启动 U 盘.备份 EFI/boot/loader.efi 成 EFI/boot/gummiboot.efi.</p><p>拷贝两份 grubx64_standalone.efi. 分别命名为 EFI/boot/loader.efi 和 EFI/boot/bootx64.efi.</p><p>然后新建一个 EFI/boot/grub.cfg 把 <a href="https://wiki.archlinux.org/index.php/Unified_Extensible_Firmware_Interface#USB_media_gets_struck_with_black_screen" target="_blank" rel="noreferrer">wiki</a>上的内容拷贝过去.记得替换掉 ARCH_YYYYMM 的值.</p><p>然后这样就应该用 grub 启动了. 如果你这样还是启动失败了, 得到了类似 <code>invalid magic number</code>的错误.那只能说你跟我一样倒霉.</p><h2 id="用-grub-挂载-iso-进行引导" tabindex="-1">用 GRUB 挂载 ISO 进行引导 <a class="header-anchor" href="#用-grub-挂载-iso-进行引导" aria-label="Permalink to &quot;用 GRUB 挂载 ISO 进行引导&quot;">​</a></h2><p>既然我们的 GRUB 是好的,那我们就用 GRUB 直接引导一个完整的 ISO 文件. 参考我之前发布的文章<a href="https://blog.icehoney.me/posts/2013-04-25-grub2-boot-from-iso" target="_blank" rel="noreferrer">使用 GRUB2 引导 ISO 镜像</a>.</p><p>在原有的 grub.cfg 上添加一个 menuentry.并把完整的 ISO 镜像拷贝到 U 盘里面.记得替换 UUID 和文件名.</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>menuentry &quot;Archlinux-x86_64.iso&quot; --class iso {</span></span>
<span class="line"><span>  set isofile=&quot;/archlinux-2013.04.01-dual.iso&quot;</span></span>
<span class="line"><span>  search -s -f -n /archlinux-2013.04.01-dual.iso</span></span>
<span class="line"><span>  probe --set=DB7B-2C3D -u $root</span></span>
<span class="line"><span>  loopback loop /archlinux-2013.04.01-dual.iso</span></span>
<span class="line"><span>  linux (loop)/arch/boot/x86_64/vmlinuz archisolabel=ARCH_201304 img_dev=/dev/disk/by-uuid/DB7B-2C3D  img_loop=$isofile earlymodules=loop</span></span>
<span class="line"><span>  initrd (loop)/arch/boot/x86_64/archiso.img</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这次总算可以引导出 arch 的安装环境了.接下来就是按照正常的步骤进行安装了. 在 Win 下直接使用<a href="https://github.com/pbatard/rufus" target="_blank" rel="noreferrer">Rufus</a>刻录就没那么折腾了.</p><h2 id="安装-archlinux-之后配置双系统的-grub" tabindex="-1">安装 Archlinux 之后配置双系统的 GRUB <a class="header-anchor" href="#安装-archlinux-之后配置双系统的-grub" aria-label="Permalink to &quot;安装 Archlinux 之后配置双系统的 GRUB&quot;">​</a></h2><p>到最后我们要<a href="https://wiki.archlinux.org/index.php/GRUB#UEFI_systems" target="_blank" rel="noreferrer">安装 GRUB 到 UEFI</a>上.如果你提前安装过 Windows,那么你肯定有 EFI 分区的.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># pacman -S dosfstools grub efibootmgr</span></span>
<span class="line"><span style="color:#6A737D;"># mkdir /boot/efi</span></span>
<span class="line"><span style="color:#6A737D;"># mount /dev/sda1 /boot/efi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>把 EFI 分区挂载到系统上,然后安装 GRUB.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># grub-install --target=x86_64-efi --efi-directory=/boot/efi --bootloader-id=grub --recheck</span></span>
<span class="line"><span style="color:#6A737D;"># grub-mkconfig -o /boot/grub/grub.cfg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>生成的 grub.cfg 里面并没有 Windows 的启动菜单,我们需要手动写.</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>menuentry &quot;Microsoft Windows 10&quot; {</span></span>
<span class="line"><span>    insmod part_gpt</span></span>
<span class="line"><span>    insmod fat</span></span>
<span class="line"><span>    insmod search_fs_uuid</span></span>
<span class="line"><span>    insmod chain</span></span>
<span class="line"><span>    search --fs-uuid --set=root $hints_string $fs_uuid</span></span>
<span class="line"><span>    chainloader /EFI/Microsoft/Boot/bootmgfw.efi</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>$hints_string 的值是命令<code># grub-probe --target=hints_string /boot/efi/EFI/Microsoft/Boot/bootmgfw.efi</code>的输出.</p><p>$fs_uuid 的值是命令<code># grub-probe --target=fs_uuid /boot/efi/EFI/Microsoft/Boot/bootmgfw.efi</code>的输出.</p><p>替换这俩值,保存并退出即可.到此双系统配置完毕.最后别忘了进 BIOS 把第一启动项目设置为 GRUB.</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://gist.github.com/miguelfrde/5dde43aa08b076106b9e" target="_blank" rel="noreferrer">Preinstalled Windows 8.1 and Arch Linux dual boot</a></p><p><a href="https://wiki.archlinux.org/index.php/Unified_Extensible_Firmware_Interface#USB_media_gets_struck_with_black_screen" target="_blank" rel="noreferrer">Unified Extensible Firmware Interface</a></p><p><a href="https://wiki.archlinux.org/index.php/USB_flash_installation_media#Using_manual_formatting" target="_blank" rel="noreferrer">USB flash installation media</a></p><p><a href="https://wiki.archlinux.org/index.php/Syslinux#Manual_install" target="_blank" rel="noreferrer">Syslinux</a></p><p><a href="https://wiki.archlinux.org/index.php/GRUB#UEFI_systems" target="_blank" rel="noreferrer">GRUB</a></p>`,48)])])}const h=s(l,[["render",i]]);export{b as __pageData,h as default};
